// Package config читает переменные окружения и валидирует их.
package config

import (
	"errors"
	"log/slog"
	"os"
	"strings"
)

// Config содержит конфигурацию бота.
type Config struct {
	TelegramBotToken      string
	OpenWeatherAPIKey     string
	TelegramBaseURL       string
	OpenWeatherBaseURL    string
	LogLevel              slog.Level
}

// Load читает и валидирует конфигурацию.
func Load() (*Config, error) {
	var errs []error

	telegramBotToken := os.Getenv("TELEGRAM_BOT_TOKEN")
	if telegramBotToken == "" {
		errs = append(errs, errors.New("TELEGRAM_BOT_TOKEN is required"))
	}

	openWeatherAPIKey := os.Getenv("OPENWEATHER_API_KEY")
	if openWeatherAPIKey == "" {
		errs = append(errs, errors.New("OPENWEATHER_API_KEY is required"))
	}

	telegramBaseURL := os.Getenv("TELEGRAM_BASE_URL")
	if telegramBaseURL == "" {
		telegramBaseURL = "https://api.telegram.org"
	}

	openWeatherBaseURL := os.Getenv("OPENWEATHER_BASE_URL")
	if openWeatherBaseURL == "" {
		openWeatherBaseURL = "https://api.openweathermap.org"
	}

	logLevelStr := strings.ToLower(os.Getenv("LOG_LEVEL"))
	logLevel := slog.LevelInfo
	switch logLevelStr {
	case "debug":
		logLevel = slog.LevelDebug
	case "info":
		logLevel = slog.LevelInfo
	case "warn":
		logLevel = slog.LevelWarn
	case "error":
		logLevel = slog.LevelError
	default:
		if logLevelStr != "" {
			errs = append(errs, errors.New("invalid LOG_LEVEL: must be debug/info/warn/error"))
		}
	}

	if len(errs) > 0 {
		return nil, errors.Join(errs...)
	}

	return &Config{
		TelegramBotToken:   telegramBotToken,
		OpenWeatherAPIKey:  openWeatherAPIKey,
		TelegramBaseURL:    telegramBaseURL,
		OpenWeatherBaseURL: openWeatherBaseURL,
		LogLevel:           logLevel,
	}, nil
}

// Package usecase содержит бизнес-логику бота.
package usecase

import (
	"context"
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"

	"weatherbot/internal/domain"
)

const maxCityRunes = 64

// WeatherProvider — источник текущей погоды.
type WeatherProvider interface {
	Current(ctx context.Context, city string) (domain.Weather, error)
}

// WeatherService отдаёт погоду по названию города.
type WeatherService struct {
	provider WeatherProvider
}

// NewWeatherService создаёт сервис поверх провайдера погоды.
func NewWeatherService(provider WeatherProvider) *WeatherService {
	return &WeatherService{provider: provider}
}

// Current валидирует город и запрашивает погоду у провайдера.
func (s *WeatherService) Current(ctx context.Context, rawCity string) (domain.Weather, error) {
	city, err := normalizeCity(rawCity)
	if err != nil {
		return domain.Weather{}, err
	}
	w, err := s.provider.Current(ctx, city)
	if err != nil {
		return domain.Weather{}, fmt.Errorf("get current weather: %w", err)
	}
	return w, nil
}

func normalizeCity(raw string) (string, error) {
	city := strings.Join(strings.Fields(raw), " ")
	if n := utf8.RuneCountInString(city); n == 0 || n > maxCityRunes {
		return "", domain.ErrInvalidCity
	}
	for _, r := range city {
		if !unicode.IsLetter(r) && !strings.ContainsRune(" -.,", r) {
			return "", domain.ErrInvalidCity // заодно отсекает utf8.RuneError и управляющие
		}
	}
	return city, nil
}

package usecase

import (
	"context"
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"

	"weatherbot/internal/domain"
)

type mockProvider struct {
	weather domain.Weather
	err     error
}

func (m *mockProvider) Current(ctx context.Context, city string) (domain.Weather, error) {
	return m.weather, m.err
}

func TestWeatherService_Current(t *testing.T) {
	t.Run("success", func(t *testing.T) {
		service := NewWeatherService(&mockProvider{
			weather: domain.Weather{City: "Москва", Country: "RU"},
			err:     nil,
		})

		w, err := service.Current(context.Background(), "Москва")
		assert.NoError(t, err)
		assert.Equal(t, "Москва", w.City)
		assert.Equal(t, "RU", w.Country)
	})

	t.Run("invalid city - empty", func(t *testing.T) {
		service := NewWeatherService(&mockProvider{})

		w, err := service.Current(context.Background(), "")
		assert.Error(t, err)
		assert.True(t, errors.Is(err, domain.ErrInvalidCity))
		assert.Equal(t, domain.Weather{}, w)
	})

	t.Run("invalid city - too long", func(t *testing.T) {
		service := NewWeatherService(&mockProvider{})

		longCity := "a"
		for i := 0; i < 65; i++ {
			longCity += "a"
		}

		w, err := service.Current(context.Background(), longCity)
		assert.Error(t, err)
		assert.True(t, errors.Is(err, domain.ErrInvalidCity))
		assert.Equal(t, domain.Weather{}, w)
	})

	t.Run("invalid city - contains invalid chars", func(t *testing.T) {
		service := NewWeatherService(&mockProvider{})

		w, err := service.Current(context.Background(), "Москва123")
		assert.Error(t, err)
		assert.True(t, errors.Is(err, domain.ErrInvalidCity))
		assert.Equal(t, domain.Weather{}, w)
	})

	t.Run("provider error", func(t *testing.T) {
		service := NewWeatherService(&mockProvider{
			err: domain.ErrCityNotFound,
		})

		w, err := service.Current(context.Background(), "Москва")
		assert.Error(t, err)
		assert.True(t, errors.Is(err, domain.ErrCityNotFound))
		assert.Equal(t, domain.Weather{}, w)
	})
}

// Package openweather — адаптер к OpenWeatherMap Current Weather API.
package openweather

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"

	"weatherbot/internal/domain"
)

const maxBodyBytes = 1 << 20 // 1 MiB

// Client запрашивает текущую погоду у OpenWeatherMap.
type Client struct {
	baseURL    string
	apiKey     string
	httpClient *http.Client
}

// NewClient создаёт клиент. httpClient обязан иметь Timeout.
func NewClient(baseURL, apiKey string, httpClient *http.Client) *Client {
	return &Client{baseURL: baseURL, apiKey: apiKey, httpClient: httpClient}
}

type currentResponse struct {
	Name string `json:"name"`
	Sys  struct {
		Country string `json:"country"`
	} `json:"sys"`
	Main struct {
		Temp      float64 `json:"temp"`
		FeelsLike float64 `json:"feels_like"`
		Humidity  int     `json:"humidity"`
	} `json:"main"`
	Weather []struct {
		Description string `json:"description"`
	} `json:"weather"`
	Wind struct {
		Speed float64 `json:"speed"`
		Deg   int     `json:"deg"`
	} `json:"wind"`
}

// Current возвращает текущую погоду в городе.
func (c *Client) Current(ctx context.Context, city string) (domain.Weather, error) {
	u, err := url.Parse(c.baseURL)
	if err != nil {
		return domain.Weather{}, fmt.Errorf("parse base url: %w", err)
	}
	u = u.JoinPath("data", "2.5", "weather")
	q := url.Values{}
	q.Set("q", city)
	q.Set("units", "metric")
	q.Set("lang", "ru")
	q.Set("appid", c.apiKey)
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return domain.Weather{}, fmt.Errorf("build request: %w", err)
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return domain.Weather{}, fmt.Errorf("%w: %s", domain.ErrProviderUnavailable, c.redact(err.Error()))
	}
	defer resp.Body.Close()

	if err := statusError(resp.StatusCode); err != nil {
		return domain.Weather{}, err
	}
	var body currentResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxBodyBytes)).Decode(&body); err != nil {
		return domain.Weather{}, fmt.Errorf("%w: decode response: %v", domain.ErrProviderUnavailable, err)
	}
	return toDomain(body), nil
}

func statusError(code int) error {
	switch {
	case code == http.StatusOK:
		return nil
	case code == http.StatusNotFound:
		return domain.ErrCityNotFound
	case code == http.StatusUnauthorized:
		return domain.ErrProviderAuth
	case code == http.StatusTooManyRequests:
		return domain.ErrRateLimited
	default:
		return fmt.Errorf("%w: status %d", domain.ErrProviderUnavailable, code)
	}
}

func toDomain(r currentResponse) domain.Weather {
	w := domain.Weather{
		City: r.Name, Country: r.Sys.Country,
		TempC: r.Main.Temp, FeelsLikeC: r.Main.FeelsLike, Humidity: r.Main.Humidity,
		WindSpeed: r.Wind.Speed, WindDeg: r.Wind.Deg,
	}
	if len(r.Weather) > 0 {
		w.Description = r.Weather[0].Description
	}
	return w
}

// redact убирает ключ (в сыром и URL-кодированном виде) из текста ошибки.
func (c *Client) redact(s string) string {
	if c.apiKey == "" {
		return s
	}
	s = strings.ReplaceAll(s, c.apiKey, "[REDACTED]")
	return strings.ReplaceAll(s, url.QueryEscape(c.apiKey), "[REDACTED]")
}

package openweather_test

import (
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"

	"weatherbot/internal/domain"
	"weatherbot/internal/repository/openweather"
)

const okBody = `{"name":"Москва","sys":{"country":"RU"},"main":{"temp":12.4,"feels_like":9.6,"humidity":71},
"weather":[{"description":"переменная облачность"}],"wind":{"speed":4.2,"deg":315}}`

func TestClientCurrent(t *testing.T) {
	tests := []struct {
		name     string
		status   int
		body     string
		wantErr  error
		wantCity string
	}{
		{name: "ok", status: http.StatusOK, body: okBody, wantCity: "Москва"},
		{name: "not found", status: http.StatusNotFound, body: `{"cod":"404","message":"city not found"}`, wantErr: domain.ErrCityNotFound},
		{name: "bad key", status: http.StatusUnauthorized, body: `{"cod":401}`, wantErr: domain.ErrProviderAuth},
		{name: "rate limited", status: http.StatusTooManyRequests, body: `{}`, wantErr: domain.ErrRateLimited},
		{name: "server error", status: http.StatusInternalServerError, body: `oops`, wantErr: domain.ErrProviderUnavailable},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				q := r.URL.Query()
				if r.URL.Path != "/data/2.5/weather" || q.Get("q") != "Москва" || q.Get("appid") != "test-key" {
					t.Errorf("unexpected request: %s", r.URL)
				}
				w.WriteHeader(tt.status)
				_, _ = io.WriteString(w, tt.body)
			}))
			t.Cleanup(srv.Close)

			c := openweather.NewClient(srv.URL, "test-key", srv.Client())
			got, err := c.Current(t.Context(), "Москва")
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("Current() err = %v, want %v", err, tt.wantErr)
			}
			if got.City != tt.wantCity {
				t.Errorf("Current() city = %q, want %q", got.City, tt.wantCity)
			}
		})
	}
}

// Package telegram — delivery-слой: взаимодействие с Telegram Bot API.
package telegram

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"

	"weatherbot/internal/domain"
)

const (
	maxBodyBytes = 1 << 20 // 1 MiB
	defaultTimeout = 40 * time.Second
)

// Sender отправляет текст в чат.
type Sender interface {
	Send(ctx context.Context, chatID int64, text string) error
}

// Client взаимодействует с Telegram Bot API.
type Client struct {
	baseURL    string
	token      string
	httpClient *http.Client
}

// NewClient создаёт клиента для работы с Telegram Bot API.
func NewClient(baseURL, token string, httpClient *http.Client) *Client {
	if httpClient == nil {
		httpClient = &http.Client{Timeout: defaultTimeout}
	}
	return &Client{baseURL: baseURL, token: token, httpClient: httpClient}
}

// Update представляет собой одно обновление от Telegram.
type Update struct {
	ID      int64 `json:"update_id"`
	Message struct {
		ID      int64  `json:"message_id"`
		Chat    struct {
			ID int64 `json:"id"`
		} `json:"chat"`
		Text string `json:"text"`
	} `json:"message"`
}

// SendMessage отправляет текст в чат.
func (c *Client) Send(ctx context.Context, chatID int64, text string) error {
	u, err := url.Parse(c.baseURL)
	if err != nil {
		return fmt.Errorf("parse base url: %w", err)
	}
	u = u.JoinPath("bot" + c.token, "sendMessage")

	q := url.Values{}
	q.Set("chat_id", fmt.Sprintf("%d", chatID))
	q.Set("text", text)
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, u.String(), nil)
	if err != nil {
		return fmt.Errorf("build request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("send message: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("send message: status %d", resp.StatusCode)
	}

	return nil
}

// GetUpdates получает обновления от Telegram.
func (c *Client) GetUpdates(ctx context.Context, offset int64) ([]Update, error) {
	u, err := url.Parse(c.baseURL)
	if err != nil {
		return nil, fmt.Errorf("parse base url: %w", err)
	}
	u = u.JoinPath("bot" + c.token, "getUpdates")

	q := url.Values{}
	q.Set("offset", fmt.Sprintf("%d", offset+1))
	q.Set("timeout", "30")
	q.Set("allowed_updates", `["message"]`)
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("build request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("get updates: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusTooManyRequests {
		// Обработка rate limiting от Telegram
		var response struct {
			Parameters struct {
				RetryAfter int `json:"retry_after"`
			} `json:"parameters"`
		}
		if err := json.NewDecoder(io.LimitReader(resp.Body, maxBodyBytes)).Decode(&response); err != nil {
			return nil, fmt.Errorf("decode rate limit response: %w", err)
		}
		if response.Parameters.RetryAfter > 0 {
			return nil, fmt.Errorf("rate limited: retry after %d seconds", response.Parameters.RetryAfter)
		}
		return nil, domain.ErrProviderUnavailable
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("get updates: status %d", resp.StatusCode)
	}

	var response struct {
		Result []Update `json:"result"`
	}
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxBodyBytes)).Decode(&response); err != nil {
		return nil, fmt.Errorf("decode updates response: %w", err)
	}

	return response.Result, nil
}

package telegram_test

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"

	"weatherbot/internal/delivery/telegram"
)

func TestClientSend(t *testing.T) {
	t.Run("success", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			assert.Equal(t, "/bottest-token/sendMessage", r.URL.Path)
			q := r.URL.Query()
			assert.Equal(t, "123456789", q.Get("chat_id"))
			assert.Equal(t, "Привет!", q.Get("text"))
			w.WriteHeader(http.StatusOK)
			_, _ = io.WriteString(w, `{"ok":true,"result":{"message_id":123}}`)
		}))
		t.Cleanup(srv.Close)

		c := telegram.NewClient(srv.URL, "test-token", srv.Client())
		err := c.Send(context.Background(), 123456789, "Привет!")
		assert.NoError(t, err)
	})

	t.Run("error status", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = io.WriteString(w, `{"ok":false,"error_code":500,"description":"Internal Server Error"}`)
		}))
		t.Cleanup(srv.Close)

		c := telegram.NewClient(srv.URL, "test-token", srv.Client())
		err := c.Send(context.Background(), 123456789, "Привет!")
		assert.Error(t, err)
	})
}

func TestClientGetUpdates(t *testing.T) {
	t.Run("success", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			assert.Equal(t, "/bottest-token/getUpdates", r.URL.Path)
			q := r.URL.Query()
			assert.Equal(t, "123", q.Get("offset"))
			assert.Equal(t, "30", q.Get("timeout"))
			assert.Equal(t, `["message"]`, q.Get("allowed_updates"))
			w.WriteHeader(http.StatusOK)
			_, _ = io.WriteString(w, `{"ok":true,"result":[{"update_id":124,"message":{"message_id":123,"chat":{"id":123456789},"text":"Привет!"}}]}`)
		}))
		t.Cleanup(srv.Close)

		c := telegram.NewClient(srv.URL, "test-token", srv.Client())
		updates, err := c.GetUpdates(context.Background(), 123)
		assert.NoError(t, err)
		assert.Len(t, updates, 1)
		assert.Equal(t, int64(124), updates[0].ID)
		assert.Equal(t, "Привет!", updates[0].Message.Text)
	})

	t.Run("rate limited", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = io.WriteString(w, `{"ok":false,"error_code":429,"description":"Too Many Requests: retry after 30","parameters":{"retry_after":30}}`)
		}))
		t.Cleanup(srv.Close)

		c := telegram.NewClient(srv.URL, "test-token", srv.Client())
		_, err := c.GetUpdates(context.Background(), 123)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "retry after")
	})

	t.Run("error status", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = io.WriteString(w, `{"ok":false,"error_code":500,"description":"Internal Server Error"}`)
		}))
		t.Cleanup(srv.Close)

		c := telegram.NewClient(srv.URL, "test-token", srv.Client())
		_, err := c.GetUpdates(context.Background(), 123)
		assert.Error(t, err)
	})
}

// Package telegram — delivery-слой: long polling Telegram Bot API и обработка команд.
package telegram

import (
	"context"
	"errors"
	"log/slog"
	"strings"
	"sync"
	"time"

	"weatherbot/internal/domain"
)

const perChatInterval = 2 * time.Second

// WeatherGetter — то, что handler'у нужно от usecase.
type WeatherGetter interface {
	Current(ctx context.Context, city string) (domain.Weather, error)
}

// Sender отправляет текст в чат.
type Sender interface {
	Send(ctx context.Context, chatID int64, text string) error
}

// Handler превращает входящее сообщение в ответ.
type Handler struct {
	weather WeatherGetter
	sender  Sender
	log     *slog.Logger
	mu      sync.Mutex
	lastReq map[int64]time.Time // token bucket ёмкостью 1 на чат
}

// NewHandler создаёт обработчик сообщений.
func NewHandler(weather WeatherGetter, sender Sender, log *slog.Logger) *Handler {
	return &Handler{weather: weather, sender: sender, log: log, lastReq: make(map[int64]time.Time)}
}

// Handle обрабатывает одно сообщение. Паника не роняет бота.
func (h *Handler) Handle(ctx context.Context, chatID int64, text string) {
	defer func() {
		if r := recover(); r != nil {
			h.log.Error("handle message panicked", "chat_id", chatID, "panic", r)
		}
	}()
	reply := msgTooFrequent
	if h.allow(chatID, time.Now()) {
		reply = h.respond(ctx, text)
	}
	if err := h.sender.Send(ctx, chatID, reply); err != nil {
		h.log.Warn("send message", "chat_id", chatID, "err", err) // Sender уже вернул redacted-ошибку
	}
}

func (h *Handler) respond(ctx context.Context, text string) string {
	cmd, city := parseCommand(text)
	switch {
	case cmd == "/start":
		return msgStart
	case cmd != "/weather" && cmd != "":
		return msgHelp
	case city == "":
		return msgEmptyCity
	}
	w, err := h.weather.Current(ctx, city)
	switch {
	case err == nil:
		return formatWeather(w)
	case errors.Is(err, domain.ErrInvalidCity):
		return msgInvalidCity
	case errors.Is(err, domain.ErrCityNotFound):
		return msgCityNotFound(city)
	default:
		h.log.Warn("weather request failed", "err", err)
		return msgUnavailable
	}
}

func (h *Handler) allow(chatID int64, now time.Time) bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	if last, ok := h.lastReq[chatID]; ok && now.Sub(last) < perChatInterval {
		return false
	}
	h.lastReq[chatID] = now
	return true
}

// parseCommand: "/weather@MyBot Казань" → ("/weather", "Казань"); "Казань" → ("", "Казань").
func parseCommand(text string) (cmd, arg string) {
	text = strings.TrimSpace(text)
	if !strings.HasPrefix(text, "/") {
		return "", text
	}
	head, rest, _ := strings.Cut(text, " ")
	head, _, _ = strings.Cut(head, "@")
	return strings.ToLower(head), strings.TrimSpace(rest)
}

package telegram_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"

	"weatherbot/internal/delivery/telegram"
	"weatherbot/internal/domain"
)

type mockWeatherGetter struct {
	mock.Mock
}

func (m *mockWeatherGetter) Current(ctx context.Context, city string) (domain.Weather, error) {
	args := m.Called(ctx, city)
	return args.Get(0).(domain.Weather), args.Error(1)
}

type mockSender struct {
